import * as retry from "./retry.ts";

export function deliveryDelay(attempts: number): number {
  retry.initialize();
  return retry.evaluate(attempts, 0.1, "background") / retry.retryUnit;
}

export function deliveryQuote(attempts: number): number {
  return retry.retryQuote(attempts, 0.1, "background").amount / retry.retryUnit;
}

export function deliveryLabel(topic: string, attempts: number): string {
  return `${topic}:${retry.normalizeAttempts(attempts)} attempts`;
}

export const projectName = "events";
export * from "./types.ts";
export * from "./logic.ts";
export * from "./selectors.ts";
export * from "./retry.ts";
export * from "./delivery.ts";

import type { EventRecord } from "./types.ts";
export function dispatch(events: EventRecord[], name: string): unknown[] { return events.filter((event) => event.name === name).map((event) => event.payload); }
export function count(events: EventRecord[], name: string): number { return dispatch(events, name).length; }

export const retryUnit = 1;
const configuration = { rate: 0.1 };
const history: number[] = [];

export function retryDelay(attempts: number, multiplier: number = configuration.rate, queue?: string): number {
  if (attempts < 0) throw new RangeError("attempts");
  history.splice(0, history.length, attempts);
  const priorities = [multiplier, multiplier / 2];
  return (attempts * (1 - priorities[0]!) + Math.min(attempts, 8) + (queue === "priority" ? 1 : 0)) * retryUnit;
}

export const evaluate = retryDelay;

export function retryQuote(attempts: number, multiplier: number = configuration.rate, queue?: string) {
  const amount = evaluate(attempts, multiplier, queue);
  return { amount, value: amount };
}

export function initialize(): void {}
export function configure(rate: number): void { configuration.rate = rate; }
export function reset(): void { history.length = 0; configuration.rate = 0.1; }
export function historySize(): number { return history.length; }
export function normalizeAttempts(attempts: number): number { return Math.max(0, Math.floor(attempts)); }

import type { EventRecord } from "./types.ts";
import { count } from "./logic.ts";
export function summary(events: EventRecord[]): Record<string, number> { return Object.fromEntries([...new Set(events.map((event) => event.name))].map((name) => [name, count(events, name)])); }
